def compact_even(a):
    write = 0
    for read in range(len(a)):
        if a[read] % 2 == 0:
            a[write] = a[read]
            write += 1
    return write

def binary_search(nums, target):
    left, right = 0, len(nums)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid
    return -1

