def is_anagram(s, t):
    if len(s) != len(t):
        return False
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch in t:
        if counts.get(ch, 0) == 0:
            return False
        counts[ch] -= 1
    return True

from collections import Counter

def common_chars(words):
    if not words:
        return []
    common = Counter(words[0])
    for word in words[1:]:
        current = Counter(word)
        for ch in common:
            common[ch] = min(common[ch], current[ch])
    return [ch for ch in sorted(common) for _ in range(common[ch])]

