def digit_square_sum(n):
    total = 0
    while n:
        n, digit = divmod(n, 10)
        total += digit * digit
    return total

def is_happy(n):
    if n <= 0:
        return False
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = digit_square_sum(n)
    return n == 1

