def three_sum(nums):
    a = sorted(nums)
    out = []
    for i in range(len(a) - 2):
        if i > 0 and a[i] == a[i - 1]:
            continue
        if a[i] > 0:
            break
        left, right = i + 1, len(a) - 1
        while left < right:
            total = a[i] + a[left] + a[right]
            if total < 0:
                left += 1
            elif total > 0:
                right -= 1
            else:
                out.append([a[i], a[left], a[right]])
                left += 1
                right -= 1
                while left < right and a[left] == a[left - 1]:
                    left += 1
                while left < right and a[right] == a[right + 1]:
                    right -= 1
    return out

def four_sum(nums, target):
    a = sorted(nums)
    n = len(a)
    out = []
    for i in range(n - 3):
        if i > 0 and a[i] == a[i - 1]:
            continue
        if a[i] + a[i+1] + a[i+2] + a[i+3] > target:
            break
        if a[i] + a[n-3] + a[n-2] + a[n-1] < target:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and a[j] == a[j - 1]:
                continue
            if a[i] + a[j] + a[j+1] + a[j+2] > target:
                break
            if a[i] + a[j] + a[n-2] + a[n-1] < target:
                continue
            left, right = j + 1, n - 1
            while left < right:
                total = a[i] + a[j] + a[left] + a[right]
                if total < target:
                    left += 1
                elif total > target:
                    right -= 1
                else:
                    out.append([a[i], a[j], a[left], a[right]])
                    left += 1
                    right -= 1
                    while left < right and a[left] == a[left - 1]:
                        left += 1
                    while left < right and a[right] == a[right + 1]:
                        right -= 1
    return out

